// Gather all data
const calls = $('Get All Call Logs').all();
const orders = $('Get All Orders').all();
const handoffs = $('Get All Handoffs').all();

// Date filtering helpers
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const yesterday = new Date(today.getTime() - 24 * 60 * 60 * 1000);
const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);
const monthAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);

// Filter calls by time period
const todayCalls = calls.filter(c => new Date(c.json.fields.Call_Start) >= today);
const weekCalls = calls.filter(c => new Date(c.json.fields.Call_Start) >= weekAgo);
const monthCalls = calls.filter(c => new Date(c.json.fields.Call_Start) >= monthAgo);

// Calculate metrics
const totalCalls = calls.length;
const aiHandledCalls = calls.filter(c => c.json.fields.Handled_By === 'AI').length;
const staffHandledCalls = calls.filter(c => c.json.fields.Handled_By === 'Staff').length;
const transferredCalls = calls.filter(c => c.json.fields.Status === 'Transferred').length;

// Order metrics
const totalOrders = orders.length;
const aiOrders = orders.filter(o => o.json.fields.Source === 'AI Phone').length;
const totalRevenue = orders.reduce((sum, o) => sum + (parseFloat(o.json.fields.Estimated_Total) || 0), 0);
const aiRevenue = orders
  .filter(o => o.json.fields.Source === 'AI Phone')
  .reduce((sum, o) => sum + (parseFloat(o.json.fields.Estimated_Total) || 0), 0);

// Duration metrics
const aiCallDurations = calls
  .filter(c => c.json.fields.Handled_By === 'AI' && c.json.fields.Duration_Seconds)
  .map(c => c.json.fields.Duration_Seconds);
const avgDuration = aiCallDurations.length > 0 
  ? aiCallDurations.reduce((a, b) => a + b, 0) / aiCallDurations.length 
  : 0;

// Peak hours analysis
const hourCounts = {};
calls.forEach(c => {
  const hour = c.json.fields.Hour_Of_Day;
  if (hour !== undefined) {
    hourCounts[hour] = (hourCounts[hour] || 0) + 1;
  }
});
const peakHour = Object.entries(hourCounts)
  .sort((a, b) => b[1] - a[1])[0];

// Day of week analysis
const dayCounts = {};
calls.forEach(c => {
  const day = c.json.fields.Day_Of_Week;
  if (day) {
    dayCounts[day] = (dayCounts[day] || 0) + 1;
  }
});
const busiestDay = Object.entries(dayCounts)
  .sort((a, b) => b[1] - a[1])[0];

// Handoff analysis
const handoffReasons = {};
handoffs.forEach(h => {
  const reason = h.json.fields.Reason || 'Unknown';
  handoffReasons[reason] = (handoffReasons[reason] || 0) + 1;
});

// Cost analysis
const totalCost = calls.reduce((sum, c) => sum + (parseFloat(c.json.fields.Estimated_Cost) || 0), 0);

// Today's metrics
const todayAICalls = todayCalls.filter(c => c.json.fields.Handled_By === 'AI').length;
const todayOrders = orders.filter(o => new Date(o.json.fields.Order_Time) >= today).length;
const todayRevenue = orders
  .filter(o => new Date(o.json.fields.Order_Time) >= today)
  .reduce((sum, o) => sum + (parseFloat(o.json.fields.Estimated_Total) || 0), 0);

return {
  summary: {
    totalCalls,
    aiHandledCalls,
    staffHandledCalls,
    transferredCalls,
    handoffRate: totalCalls > 0 ? ((transferredCalls / aiHandledCalls) * 100).toFixed(1) : 0,
    aiHandleRate: totalCalls > 0 ? ((aiHandledCalls / totalCalls) * 100).toFixed(1) : 0
  },
  orders: {
    totalOrders,
    aiOrders,
    totalRevenue: totalRevenue.toFixed(2),
    aiRevenue: aiRevenue.toFixed(2),
    revenueRecovered: aiRevenue.toFixed(2)
  },
  performance: {
    avgCallDuration: avgDuration.toFixed(1),
    totalCost: totalCost.toFixed(2),
    costPerCall: totalCalls > 0 ? (totalCost / totalCalls).toFixed(4) : 0,
    costPerOrder: aiOrders > 0 ? (totalCost / aiOrders).toFixed(4) : 0
  },
  patterns: {
    peakHour: peakHour ? `${peakHour[0]}:00` : 'N/A',
    peakHourCalls: peakHour ? peakHour[1] : 0,
    busiestDay: busiestDay ? busiestDay[0] : 'N/A',
    busiestDayCalls: busiestDay ? busiestDay[1] : 0,
    hourlyDistribution: hourCounts,
    dailyDistribution: dayCounts
  },
  handoffs: {
    total: handoffs.length,
    reasons: handoffReasons
  },
  today: {
    calls: todayCalls.length,
    aiCalls: todayAICalls,
    orders: todayOrders,
    revenue: todayRevenue.toFixed(2)
  },
  generatedAt: now.toISOString()
};
